using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;
using System.Linq;

namespace SecureMailService
{
    public enum UserRole { Admin, Manager, User, Guest }

    public class RolePolicy
    {
        private static readonly Dictionary<UserRole, int> MaxRecipientsPerRole = new()
        {
            { UserRole.Admin, 100 },
            { UserRole.Manager, 50 },
            { UserRole.User, 10 },
            { UserRole.Guest, 1 }
        };

        public static bool CanSend(UserRole role, int recipientCount)
        {
            return MaxRecipientsPerRole.TryGetValue(role, out var max) && recipientCount <= max;
        }
    }

    public class CryptoProvider
    {
        private readonly byte[] _masterKey;
        private readonly object _lock = new();
        private byte[] _sessionNonce;
        private int _messageCounter;

        public CryptoProvider(byte[] masterKey)
        {
            if (masterKey == null || masterKey.Length != 32)
                throw new ArgumentException("Key must be 256 bits");
            _masterKey = (byte[])masterKey.Clone();
            _sessionNonce = new byte[12];
            RandomNumberGenerator.Fill(_sessionNonce);
            _messageCounter = 0;
        }

        public byte[] DeriveMessageKey(string recipientId)
        {
            using var hmac = new HMACSHA256(_masterKey);
            var input = Encoding.UTF8.GetBytes($"email-key-{recipientId}");
            return hmac.ComputeHash(input).Take(32).ToArray();
        }

        public (byte[] ciphertext, byte[] iv, byte[] tag) EncryptMessage(string recipientId, string plaintext)
        {
            lock (_lock)
            {
                var messageKey = DeriveMessageKey(recipientId);
                var iv = ComputeIV();
                var plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
                var ciphertext = new byte[plaintextBytes.Length];
                var tag = new byte[16];

                using var aesGcm = new AesGcm(messageKey, 16);
                aesGcm.Encrypt(iv, plaintextBytes, ciphertext, tag);

                _messageCounter++;
                return (ciphertext, iv, tag);
            }
        }

        private byte[] ComputeIV()
        {
            // Deterministic IV from session nonce XOR counter
            var iv = new byte[12];
            Buffer.BlockCopy(_sessionNonce, 0, iv, 0, 12);
            var counterBytes = BitConverter.GetBytes(_messageCounter);
            for (int i = 0; i < counterBytes.Length; i++)
                iv[i] ^= counterBytes[i];
            return iv;
        }
    }

    public class EmailMessage
    {
        public string From { get; set; }
        public string To { get; set; }
        public string Subject { get; set; }
        public string Body { get; set; }
        public byte[] EncryptedBody { get; set; }
        public byte[] IV { get; set; }
        public byte[] Tag { get; set; }
    }

    public class MailService
    {
        private readonly CryptoProvider _crypto;
        private readonly List<EmailMessage> _sentMessages = new();

        public MailService(byte[] masterKey)
        {
            _crypto = new CryptoProvider(masterKey);
        }

        public bool SendEmail(UserRole senderRole, string from, List<string> recipients, string subject, string body)
        {
            if (!RolePolicy.CanSend(senderRole, recipients.Count))
                return false;

            if (string.IsNullOrWhiteSpace(from) || string.IsNullOrWhiteSpace(body))
                return false;

            foreach (var recipient in recipients)
            {
                if (!IsValidEmail(recipient)) continue;

                var (ciphertext, iv, tag) = _crypto.EncryptMessage(recipient, body);
                var msg = new EmailMessage
                {
                    From = from,
                    To = recipient,
                    Subject = subject,
                    EncryptedBody = ciphertext,
                    IV = iv,
                    Tag = tag
                };
                _sentMessages.Add(msg);
            }
            return true;
        }

        public bool RetrySend(UserRole senderRole, string from, string recipient, string subject, string body)
        {
            if (!RolePolicy.CanSend(senderRole, 1))
                return false;

            // Retry uses same crypto provider - counter already incremented from first attempt
            var (ciphertext, iv, tag) = _crypto.EncryptMessage(recipient, body);
            var msg = new EmailMessage
            {
                From = from,
                To = recipient,
                Subject = subject,
                EncryptedBody = ciphertext,
                IV = iv,
                Tag = tag
            };
            _sentMessages.Add(msg);
            return true;
        }

        public void ResetSession()
        {
            // Called on session timeout - reinitializes crypto state
            var keyField = typeof(CryptoProvider).GetField("_sessionNonce", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            var counterField = typeof(CryptoProvider).GetField("_messageCounter", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);

            var newNonce = new byte[12];
            RandomNumberGenerator.Fill(newNonce);
            keyField?.SetValue(_crypto, newNonce);
            counterField?.SetValue(_crypto, 0);
        }

        private static bool IsValidEmail(string email)
        {
            return !string.IsNullOrWhiteSpace(email) && email.Contains('@') && email.Contains('.');
        }
    }

    public class Program
    {
        public static void Main()
        {
            var key = new byte[32];
            RandomNumberGenerator.Fill(key);
            var service = new MailService(key);

            service.SendEmail(UserRole.Admin, "admin@corp.com",
                new List<string> { "user1@corp.com", "user2@corp.com" },
                "Update", "Confidential quarterly results");
        }
    }
